export interface BookInput {
  title: string;
  author: string;
  publishedYear: number;
  genre: string;
}

export interface Book extends BookInput {
  id: string;
  ownerId: string;
}

export type AddBookResult =
  | { ok: true; books: Book[]; book: Book }
  | { ok: false; errors: string[]; books: Book[] };

export function addBook(
  existing: readonly Book[],
  ownerId: string,
  id: string,
  input: BookInput,
): AddBookResult {
  const errors: string[] = [];
  if (ownerId.trim() === '') errors.push('ownerId');
  if (id.trim() === '') errors.push('id');
  if (input.title.trim() === '') errors.push('title');
  if (input.author.trim() === '') errors.push('author');
  if (!Number.isInteger(input.publishedYear) || input.publishedYear < 1450 || input.publishedYear >= 2100) errors.push('publishedYear');
  if (input.genre.trim() === '') errors.push('genre');
  if (existing.some(book => book.id === id.trim())) errors.push('duplicateId');

  const copies = existing.map(book => ({ ...book }));
  if (errors.length > 0) return { ok: false, errors, books: copies };

  const created: Book = {
    id: id.trim(),
    ownerId: ownerId.trim(),
    title: input.title.trim(),
    author: input.author.trim(),
    publishedYear: input.publishedYear,
    genre: input.genre.trim(),
  };
  return { ok: true, books: [...copies, { ...created }], book: { ...created } };
}

