import { addBook, type Book, type BookInput } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

const existing: readonly Book[] = [
  { id: 'old', ownerId: 'owner-a', title: 'Existing', author: 'Writer', publishedYear: 2000, genre: 'Drama' },
  { id: 'dup', ownerId: 'owner-b', title: 'Second', author: 'Author', publishedYear: 1999, genre: 'History' },
];
const existingSnapshot = JSON.stringify(existing);
const input: BookInput = { title: '  New Book  ', author: '\tNew Author ', publishedYear: 1450, genre: ' Fiction\n' };
const inputSnapshot = JSON.stringify(input);
const result = addBook(existing, ' owner-c ', ' new-id ', input);
assert(result.ok, 'valid book should be added');
if (result.ok) {
  equal(result.books, [...existing, {
    id: 'new-id', ownerId: 'owner-c', title: 'New Book', author: 'New Author', publishedYear: 1450, genre: 'Fiction',
  }], 'trimmed book append');
  assert(result.books !== existing, 'books array must be fresh');
  assert(result.books[0] !== existing[0] && result.books[1] !== existing[1], 'existing books must be copied');
  const entry = result.books[result.books.length - 1];
  assert(result.book !== entry, 'returned book must not alias array entry');
  result.book.title = 'changed';
  assert(entry.title === 'New Book', 'separate returned book copy');
}
assert(JSON.stringify(existing) === existingSnapshot, 'existing books must not mutate');
assert(JSON.stringify(input) === inputSnapshot, 'input must not mutate');

const invalid = addBook(existing, ' ', ' dup ', {
  title: '', author: '\t', publishedYear: 1449, genre: '   ',
});
assert(!invalid.ok, 'invalid data should fail');
if (!invalid.ok) {
  equal(invalid.errors, ['ownerId', 'title', 'author', 'publishedYear', 'genre', 'duplicateId'], 'all errors in required order');
  equal(invalid.books, existing, 'failure preserves content and order');
  assert(invalid.books !== existing, 'failure array must be fresh');
  invalid.books.forEach((book, index) => assert(book !== existing[index], 'failure books must be copied'));
}

const blankId = addBook([], 'owner', '\n', { title: 'T', author: 'A', publishedYear: 2100, genre: 'G' });
assert(!blankId.ok, 'blank id fails');
if (!blankId.ok) equal(blankId.errors, ['id'], 'blank id error');

const tooLate = addBook([], 'owner', 'id', { title: 'T', author: 'A', publishedYear: 2101, genre: 'G' });
assert(!tooLate.ok, 'year above boundary fails');
if (!tooLate.ok) equal(tooLate.errors, ['publishedYear'], 'late year error');
const fractional = addBook([], 'owner', 'id', { title: 'T', author: 'A', publishedYear: 2000.5, genre: 'G' });
assert(!fractional.ok, 'fractional year fails');

const upperBoundary = addBook([], 'o', 'i', { title: 'T', author: 'A', publishedYear: 2100, genre: 'G' });
assert(upperBoundary.ok, '2100 is valid');
const trimmedDuplicate = addBook(existing, 'o', ' dup ', { title: 'T', author: 'A', publishedYear: 2000, genre: 'G' });
assert(!trimmedDuplicate.ok, 'trimmed duplicate id fails');
if (!trimmedDuplicate.ok) equal(trimmedDuplicate.errors, ['duplicateId'], 'duplicate error');

